package com.studentforum;

import java.util.List;
import java.util.Map;
import org.apache.ibatis.annotations.*;

@Mapper
public interface ForumMapper {
    @Select("SELECT u.id,u.email,u.username,u.role,u.status,u.moderator_board_id,mb.name AS moderator_board_name,u.points,u.reputation,u.message_privacy,u.notify_unfollow,u.notify_mention,u.school,u.grade,u.major,u.subject_preference,u.public_school,u.public_grade,u.created_at FROM users u LEFT JOIN boards mb ON mb.id=u.moderator_board_id WHERE u.id=#{id}") Map<String,Object> user(long id);
    @Select("SELECT id,password_hash,status,role FROM users WHERE email=#{email}") Map<String,Object> credentials(String email);
    @Select("SELECT COUNT(*) FROM users WHERE email=#{email} OR username=#{username}") int userExists(@Param("email") String email,@Param("username") String username);
    @Insert("INSERT INTO users(email,username,password_hash) VALUES(#{email},#{username},#{hash})") @Options(useGeneratedKeys=true,keyProperty="id") void insertUser(Map<String,Object> user);
    @Update("UPDATE users SET last_login_at=NOW() WHERE id=#{id}") void login(long id);
    @Update("UPDATE users SET school=#{school},grade=#{grade},major=#{major},subject_preference=#{subject},public_school=#{publicSchool},public_grade=#{publicGrade} WHERE id=#{id}") void profile(@Param("id") long id,@Param("school") String school,@Param("grade") String grade,@Param("major") String major,@Param("subject") String subject,@Param("publicSchool") boolean publicSchool,@Param("publicGrade") boolean publicGrade);
    @Update("UPDATE users SET password_hash=#{hash} WHERE id=#{id}") void password(@Param("id") long id,@Param("hash") String hash);
    @Select("SELECT password_hash FROM users WHERE id=#{id}") String hash(long id);
    @Select("SELECT id,name,slug,description,sort_order FROM boards WHERE status='enabled' ORDER BY sort_order,id") List<Map<String,Object>> boards();
    @Select("SELECT id,name FROM tags WHERE status='enabled' ORDER BY name") List<Map<String,Object>> tags();
    @Select("SELECT id,name FROM boards WHERE id=#{id} AND status='enabled'") Map<String,Object> board(long id);
    @Select("SELECT id,name FROM tags WHERE id=#{id} AND status='enabled'") Map<String,Object> tag(long id);
    @Select("SELECT p.*,u.username,u.points AS author_points,u.role AS author_role,mb.name AS author_board_name,b.name AS board_name,(SELECT COUNT(*) FROM replies r WHERE r.post_id=p.id AND r.status='published') AS reply_count,(SELECT COUNT(*) FROM favorites f WHERE f.post_id=p.id) AS favorite_count FROM posts p JOIN users u ON u.id=p.author_id LEFT JOIN boards mb ON mb.id=u.moderator_board_id JOIN boards b ON b.id=p.board_id WHERE p.id=#{id}") Map<String,Object> post(long id);
    @Select("<script>SELECT p.id,p.board_id,p.author_id,p.type,p.title,p.content,p.image_path,p.is_solved,p.is_featured,p.is_top,p.view_count,p.created_at,u.username,b.name AS board_name,(SELECT COUNT(*) FROM replies r WHERE r.post_id=p.id AND r.status='published') AS reply_count FROM posts p JOIN users u ON u.id=p.author_id JOIN boards b ON b.id=p.board_id WHERE p.status='published' <if test='board != null'>AND p.board_id=#{board}</if><if test='tag != null'>AND EXISTS(SELECT 1 FROM post_tags pt WHERE pt.post_id=p.id AND pt.tag_id=#{tag})</if><if test='type != null'>AND p.type=#{type}</if><if test='solved != null'>AND p.is_solved=#{solved}</if><if test='featured != null'>AND p.is_featured=#{featured}</if><if test='keyword != null'>AND LOCATE(LOWER(#{keyword}),LOWER(p.title)) &gt; 0</if> ORDER BY p.is_top DESC <choose><when test='sort == &quot;hot&quot;'>, (p.view_count + (SELECT COUNT(*) FROM replies r WHERE r.post_id=p.id AND r.status='published') * 5) DESC</when><otherwise>, p.created_at DESC</otherwise></choose> LIMIT #{limit} OFFSET #{offset}</script>") List<Map<String,Object>> posts(@Param("board") Long board,@Param("tag") Long tag,@Param("type") String type,@Param("solved") Boolean solved,@Param("featured") Boolean featured,@Param("keyword") String keyword,@Param("sort") String sort,@Param("limit") int limit,@Param("offset") int offset);
    @Select("SELECT t.id,t.name FROM tags t JOIN post_tags pt ON pt.tag_id=t.id WHERE pt.post_id=#{postId}") List<Map<String,Object>> postTags(long postId);
    @Insert("INSERT INTO posts(board_id,author_id,type,title,content,image_path) VALUES(#{boardId},#{authorId},#{type},#{title},#{content},#{imagePath})") @Options(useGeneratedKeys=true,keyProperty="id") void insertPost(Map<String,Object> post);
    @Insert("INSERT IGNORE INTO post_tags(post_id,tag_id) VALUES(#{postId},#{tagId})") void postTag(@Param("postId") long postId,@Param("tagId") long tagId);
    @Update("UPDATE posts SET title=#{title},content=#{content} WHERE id=#{id}") void editPost(@Param("id") long id,@Param("title") String title,@Param("content") String content);
    @Update("UPDATE posts SET status=#{status} WHERE id=#{id}") void postStatus(@Param("id") long id,@Param("status") String status);
    @Update("UPDATE posts SET view_count=view_count+1 WHERE id=#{id}") void view(long id);
    @Select("SELECT r.*,u.username,u.points AS author_points,u.role AS author_role,mb.name AS author_board_name FROM replies r JOIN users u ON u.id=r.author_id LEFT JOIN boards mb ON mb.id=u.moderator_board_id WHERE r.post_id=#{postId} AND r.status='published' ORDER BY r.is_accepted DESC,r.created_at") List<Map<String,Object>> replies(long postId);
    @Select("SELECT * FROM replies WHERE id=#{id}") Map<String,Object> reply(long id);
    @Insert("INSERT INTO replies(post_id,author_id,content,image_path) VALUES(#{postId},#{authorId},#{content},#{imagePath})") @Options(useGeneratedKeys=true,keyProperty="id") void insertReply(Map<String,Object> reply);
    @Update("UPDATE replies SET status='deleted' WHERE id=#{id}") void deleteReply(long id);
    @Update("UPDATE replies SET is_accepted=TRUE WHERE id=#{id}") void acceptReply(long id);
    @Update("UPDATE posts SET is_solved=TRUE,accepted_reply_id=#{replyId},accepted_at=NOW() WHERE id=#{postId} AND accepted_reply_id IS NULL") int acceptPost(@Param("postId") long postId,@Param("replyId") long replyId);
    @Select("SELECT COUNT(*) FROM replies WHERE post_id=#{postId} AND author_id=#{userId} AND status='published'") int priorReply(@Param("postId") long postId,@Param("userId") long userId);
    @Insert("INSERT IGNORE INTO favorites(user_id,post_id) VALUES(#{userId},#{postId})") void favorite(@Param("userId") long userId,@Param("postId") long postId);
    @Delete("DELETE FROM favorites WHERE user_id=#{userId} AND post_id=#{postId}") void unfavorite(@Param("userId") long userId,@Param("postId") long postId);
    @Select("SELECT COUNT(*) FROM favorites WHERE user_id=#{userId} AND post_id=#{postId}") int isFavorite(@Param("userId") long userId,@Param("postId") long postId);
    @Select("SELECT p.id,p.title,p.type,p.created_at,b.name AS board_name FROM favorites f JOIN posts p ON p.id=f.post_id JOIN boards b ON b.id=p.board_id WHERE f.user_id=#{userId} AND p.status='published' ORDER BY f.post_id DESC LIMIT #{limit} OFFSET #{offset}") List<Map<String,Object>> favorites(@Param("userId") long userId,@Param("limit") int limit,@Param("offset") int offset);
    @Insert("INSERT INTO notifications(user_id,kind,message,post_id) VALUES(#{userId},#{kind},#{message},#{postId})") void notifyUser(@Param("userId") long userId,@Param("kind") String kind,@Param("message") String message,@Param("postId") Long postId);
    @Select("SELECT * FROM notifications WHERE user_id=#{userId} ORDER BY created_at DESC,id DESC LIMIT #{limit} OFFSET #{offset}") List<Map<String,Object>> notifications(@Param("userId") long userId,@Param("limit") int limit,@Param("offset") int offset);
    @Select("SELECT COUNT(*) FROM notifications WHERE user_id=#{userId} AND is_read=FALSE") int unread(long userId);
    @Update("UPDATE notifications SET is_read=TRUE WHERE id=#{id} AND user_id=#{userId}") void read(@Param("userId") long userId,@Param("id") long id);
    @Update("UPDATE notifications SET is_read=TRUE WHERE user_id=#{userId}") void readAll(long userId);
    @Select("SELECT COUNT(*) FROM point_logs WHERE user_id=#{userId} AND action=#{action} AND DATE(created_at)=CURRENT_DATE()") int dailyPoints(@Param("userId") long userId,@Param("action") String action);
    @Select("SELECT COUNT(*) FROM point_logs WHERE user_id=#{userId} AND action=#{action} AND ref_type=#{refType} AND ref_id=#{refId}") int rewardExists(@Param("userId") long userId,@Param("action") String action,@Param("refType") String refType,@Param("refId") long refId);
    @Update("UPDATE users SET points=GREATEST(0,points+#{amount}) WHERE id=#{userId}") void addPoints(@Param("userId") long userId,@Param("amount") int amount);
    @Select("SELECT points FROM users WHERE id=#{id}") int points(long id);
    @Insert("INSERT INTO point_logs(user_id,action,points,balance_after,ref_type,ref_id) VALUES(#{userId},#{action},#{amount},#{balance},#{refType},#{refId})") void pointLog(@Param("userId") long userId,@Param("action") String action,@Param("amount") int amount,@Param("balance") int balance,@Param("refType") String refType,@Param("refId") Long refId);
    @Select("SELECT * FROM point_logs WHERE user_id=#{userId} ORDER BY id DESC LIMIT 100") List<Map<String,Object>> pointLogs(long userId);
    @Select("SELECT COUNT(*) FROM reports WHERE reporter_id=#{userId} AND DATE(created_at)=CURRENT_DATE()") int dailyReports(long userId);
    @Insert("INSERT INTO reports(reporter_id,target_type,target_id,reason,description) VALUES(#{userId},#{type},#{targetId},#{reason},#{description})") void report(@Param("userId") long userId,@Param("type") String type,@Param("targetId") long targetId,@Param("reason") String reason,@Param("description") String description);
    @Select("SELECT * FROM reports WHERE id=#{id}") Map<String,Object> reportById(long id);
    @Select("<script>SELECT r.*,u.username AS reporter_name FROM reports r JOIN users u ON u.id=r.reporter_id LEFT JOIN posts p ON r.target_type='post' AND p.id=r.target_id LEFT JOIN replies reply ON r.target_type='reply' AND reply.id=r.target_id LEFT JOIN posts reply_post ON reply_post.id=reply.post_id <where><if test='boardId != null'>((r.target_type='post' AND p.board_id=#{boardId}) OR (r.target_type='reply' AND reply_post.board_id=#{boardId}))</if><if test='keyword != null'>AND (LOCATE(LOWER(#{keyword}),LOWER(u.username)) &gt; 0 OR LOCATE(LOWER(#{keyword}),LOWER(r.reason)) &gt; 0)</if></where> ORDER BY (r.status='pending') DESC,r.id DESC LIMIT #{limit} OFFSET #{offset}</script>") List<Map<String,Object>> reports(@Param("keyword") String keyword,@Param("boardId") Long boardId,@Param("limit") int limit,@Param("offset") int offset);
    @Update("UPDATE reports SET status=#{status},handler_id=#{handler},handle_note=#{note},handled_at=NOW() WHERE id=#{id} AND status='pending'") int handleReport(@Param("id") long id,@Param("status") String status,@Param("handler") long handler,@Param("note") String note);
    @Update("UPDATE posts SET is_featured=#{featured},featured_at=IF(#{featured},NOW(),NULL) WHERE id=#{id} AND is_featured != #{featured}") int feature(@Param("id") long id,@Param("featured") boolean featured);
    @Update("UPDATE posts SET is_top=#{top} WHERE id=#{id}") void top(@Param("id") long id,@Param("top") boolean top);
    @Update("UPDATE users SET status=#{status} WHERE id=#{id}") void userStatus(@Param("id") long id,@Param("status") String status);
    @Update("UPDATE users SET role=#{role},moderator_board_id=#{boardId} WHERE id=#{id}") void userRole(@Param("id") long id,@Param("role") String role,@Param("boardId") Long boardId);
    @Select("SELECT COUNT(*) FROM users WHERE role='admin'") int adminCount();
    @Select("<script>SELECT u.id,u.email,u.username,u.role,u.status,u.moderator_board_id,b.name AS moderator_board_name,u.points,u.created_at FROM users u LEFT JOIN boards b ON b.id=u.moderator_board_id <if test='keyword != null'>WHERE LOCATE(LOWER(#{keyword}),LOWER(u.username)) &gt; 0</if> ORDER BY u.id DESC LIMIT #{limit} OFFSET #{offset}</script>") List<Map<String,Object>> users(@Param("keyword") String keyword,@Param("limit") int limit,@Param("offset") int offset);
    @Select("SELECT id FROM users") List<Long> allUserIds();
    @Select("<script>SELECT p.id,p.title,p.status,p.is_featured,p.is_top,p.board_id,p.created_at,u.username FROM posts p JOIN users u ON u.id=p.author_id <where><if test='keyword != null'>LOCATE(LOWER(#{keyword}),LOWER(p.title)) &gt; 0</if><if test='boards != null'>AND p.board_id IN <foreach item='board' collection='boards' open='(' separator=',' close=')'>#{board}</foreach></if></where> ORDER BY p.id DESC LIMIT #{limit} OFFSET #{offset}</script>") List<Map<String,Object>> adminPosts(@Param("keyword") String keyword,@Param("boards") List<Long> boards,@Param("limit") int limit,@Param("offset") int offset);
    @Select("SELECT (SELECT COUNT(*) FROM users) AS users,(SELECT COUNT(*) FROM posts WHERE status='published') AS posts,(SELECT COUNT(*) FROM replies WHERE status='published') AS replies,(SELECT COUNT(*) FROM posts WHERE DATE(created_at)=CURRENT_DATE()) AS today,(SELECT COUNT(*) FROM reports WHERE status='pending') AS pending") Map<String,Object> dashboard();
    @Insert("INSERT INTO admin_logs(actor_id,action,target_type,target_id,detail) VALUES(#{actor},#{action},#{type},#{target},#{detail})") void adminLog(@Param("actor") long actor,@Param("action") String action,@Param("type") String type,@Param("target") long target,@Param("detail") String detail);
    @Select("<script>SELECT * FROM admin_logs <if test='keyword != null'>WHERE LOCATE(LOWER(#{keyword}),LOWER(action)) &gt; 0 OR LOCATE(LOWER(#{keyword}),LOWER(COALESCE(detail,''))) &gt; 0</if> ORDER BY id DESC LIMIT #{limit} OFFSET #{offset}</script>") List<Map<String,Object>> adminLogs(@Param("keyword") String keyword,@Param("limit") int limit,@Param("offset") int offset);
    @Insert("INSERT INTO boards(name,slug,description,sort_order) VALUES(#{name},#{slug},#{description},#{sortOrder})") void addBoard(@Param("name") String name,@Param("slug") String slug,@Param("description") String description,@Param("sortOrder") int sortOrder);
    @Select("SELECT id,name,status FROM boards WHERE id=#{id}") Map<String,Object> adminBoard(long id);
    @Update("UPDATE boards SET status='disabled' WHERE id=#{id} AND status='enabled'") int disableBoard(long id);
    @Select("<script>SELECT id,name,slug,description,sort_order,status FROM boards <if test='keyword != null'>WHERE LOCATE(LOWER(#{keyword}),LOWER(name)) &gt; 0 OR LOCATE(LOWER(#{keyword}),LOWER(slug)) &gt; 0</if> ORDER BY status,sort_order,id LIMIT #{limit} OFFSET #{offset}</script>") List<Map<String,Object>> adminBoards(@Param("keyword") String keyword,@Param("limit") int limit,@Param("offset") int offset);
    @Update("UPDATE boards SET name=#{name},slug=#{slug},description=#{description},sort_order=#{sortOrder} WHERE id=#{id}") void editBoard(@Param("id") long id,@Param("name") String name,@Param("slug") String slug,@Param("description") String description,@Param("sortOrder") int sortOrder);
    @Update("UPDATE boards SET status='enabled' WHERE id=#{id} AND status='disabled'") int enableBoard(long id);
    @Select("SELECT COUNT(*) FROM boards WHERE slug=#{slug} AND id<>#{id}") int boardSlugTaken(@Param("slug") String slug,@Param("id") long id);
    @Insert("INSERT INTO tags(name) VALUES(#{name})") void addTag(String name);
    @Select("SELECT id,name,status FROM tags WHERE id=#{id}") Map<String,Object> adminTag(long id);
    @Update("UPDATE tags SET status='disabled' WHERE id=#{id} AND status='enabled'") int disableTag(long id);
    @Select("<script>SELECT id,name,status FROM tags <if test='keyword != null'>WHERE LOCATE(LOWER(#{keyword}),LOWER(name)) &gt; 0</if> ORDER BY status,name LIMIT #{limit} OFFSET #{offset}</script>") List<Map<String,Object>> adminTags(@Param("keyword") String keyword,@Param("limit") int limit,@Param("offset") int offset);
    @Update("UPDATE tags SET name=#{name} WHERE id=#{id}") void editTag(@Param("id") long id,@Param("name") String name);
    @Update("UPDATE tags SET status='enabled' WHERE id=#{id} AND status='disabled'") int enableTag(long id);
    @Select("SELECT COUNT(*) FROM tags WHERE name=#{name} AND id<>#{id}") int tagNameTaken(@Param("name") String name,@Param("id") long id);
    @Select("SELECT u.id,u.username,u.points,u.school,u.grade,u.public_school,u.public_grade,u.role,mb.name AS moderator_board_name FROM users u LEFT JOIN boards mb ON mb.id=u.moderator_board_id WHERE u.id=#{id}") Map<String,Object> publicUser(long id);
    @Select("SELECT COUNT(*) FROM users WHERE email=#{email}") int emailExists(String email);
    @Insert("INSERT INTO users(email,username,password_hash,role,moderator_board_id,points) VALUES(#{email},#{username},#{hash},#{role},#{boardId},5)") void demoUser(@Param("email") String email,@Param("username") String username,@Param("hash") String hash,@Param("role") String role,@Param("boardId") Long boardId);
}
